       //                                                                     *
       //  See GNU General Public License for details.                        *
       //          http://www.opensource.org                                  *
       //          http://www.opensource.org/licenses/gpl-license.html        *
       //                                                                     *
       //=====================================================================*
       //  History:                                                           *
       //                                                                     *
       //  Datum       Name          Änderung                                 *
       //  ----------  ------------  ---------------------------------------  *
       //  10.01.2003  Th.Raddatz    Removed special character § from source. *
       //  08.02.2019  Th.Raddatz    Converted to /free.                      *
       //                                                                     *
       //=====================================================================*
       // >>PRE-COMPILER<<                                                    *
       //   >>CRTCMD<< CRTRPGMOD    MODULE(&LI/&OB) +                         *
       //                           SRCFILE(&SL/&SF) +                        *
       //                           SRCMBR(&SM);                              *
       //   >>IMPORTANT<<                                                     *
       //     >>PARM<< TRUNCNBR(*NO);                                         *
       //     >>PARM<< DBGVIEW(*LIST);                                        *
       //     >>PARM<< OPTION(*EVENTF);                                       *
       //   >>END-IMPORTANT<<                                                 *
       //   >>EXECUTE<<                                                       *
       // >>END-PRE-COMPILER<<                                                *
       //=====================================================================*
       //                                                                     *
       //  INPUT-Parameter:                                                   *
       //  ================                                                   *
       //                                                                     *
       //  i_qPgm    Qualifizierte Programmname                               *
       //             1 - 10:  pgm                                            *
       //            11 - 20:  library                                        *
       //                        *ALL        Alle Bibliotheken auf dem System *
       //                        *ALLUSR     Alle nicht-IBM Bibliotheken      *
       //                        *CURLIB     Aktuelle Bibliothek des Jobs     *
       //                        *LIBL       kompl. Bibliotheksliste          *
       //                        *USRLIBL    Benutzerteil der Bibl.Liste      *
       //                                                                     *
       //  i_option  Funktionscode                                            *
       //              1 - erstellen Liste                   CREATE           *
       //              5 - lesen nächsten Eintrag            READ             *
       //              4 - löschen Liste                     DELETE           *
       //                                                                     *
       //  OUTPUT-Parameter:                                                  *
       //  =================                                                  *
       //                                                                     *
       //  o_count   Anzahl noch verfügbarer Einträge                         *
       //  o_module  Eintragsdaten                                            *
       //                                                                     *
       //=====================================================================*
     H NOMAIN
      /COPY QDSPSRC,H_SPEC
      /COPY QDSPSRC,COPYRIGHT

     D lstHdr          DS                  likeds(genLstHdr_t) based(pLstHdr)
     D pgml0100        DS                  likeds(PGML0100_t) based(pPgml0100)
     D errCode         DS                  likeds(errCode_t)

      /copy qdspsrc,types_h
      /copy qdspsrc,qusrspc
      /copy qdspsrc,genlsthdr
      /copy qdspsrc,fderrcode
      /copy qdspsrc,qbnlpgmi
      /copy qdspsrc,qcmdexc

     D qUsrSpc         DS                  likeds(qObj_t)
     D numRecords      S             10I 0
     D clCmd           S            512A   varying

     D existUserSpace...
     D                 PR              n   extproc('existUserSpace')
     D  i_qUsrSpc                          const likeds(qObj_t)

       //*******************************************************************
       //  Program entry point                                             *
       //*******************************************************************
     P DSPSRCR1...
     P                 B                   export
     D                 PI
     D  i_qPgm                             const likeds(qObj_t)
     D  i_option                      1A   const
     D  o_count                      10P 0
     D  o_module                    512A
       //---------------------------------------------------*
      /free

       qUsrSpc.name = 'DSPSRC';
       qUsrSpc.lib = 'QTEMP';

       select;
          //  Create module list
       when (i_option = '1');
          exsr CREATE;
          //  Delete list
       when (i_option = '4');
          exsr DELETE;
          //  Get next entry
       when (i_option = '5');
          exsr READ;
       endsl;

       //====================================================*
       //  CREATE --  Erstellen USRSPC und Liste             *
       //----------------------------------------------------*
       //  Erforderliche Änderungen für anderes List API     *
       //    - evtl. Initialgröße des USRSPC                 *
       //    - API Aufruf für Liste                          *
       //====================================================*
       begsr CREATE;

          if (not existUserSpace(qUsrSpc));
             QUSCRTUS(
                qUsrSpc: 'TEMP': 2048: '': '*ALL': '');
          endif;

          clear errCode;
          errCode.bytPrv = %size(errCode);

          QBNLPGMI(
            qUsrSpc: 'PGML0100': i_qPgm: errCode);

          if (errCode.bytAvl > 0);
             //  Fehler aufgetreten!
             numRecords = 0;
          else;
             //  ermitteln Offset zu den Eintragsdaten
             QUSPTRUS(qUsrSpc: pLstHdr);

             numRecords = lstHdr.numE;
          endif;

          o_count = numRecords;
          o_module = '';

       endsr;

       //====================================================*
       //  DELETE --  Löschen USRSPC                         *
       //----------------------------------------------------*
       //  Erforderliche Änderungen für anderes List API     *
       //    - *NONE                                         *
       //====================================================*
       begsr DELETE;

          if (existUserSpace(qUsrSpc));
             clCmd = 'DLTUSRSPC +
                     USRSPC(' + %trim(qUsrSpc.lib) + '/'
                              + %trim(qUsrSpc.name) + ')';
             callp(e) QCMDEXC(clCmd: %len(clCmd));
          endif;

          o_count = 0;
          o_module = '';

       endsr;

       //====================================================*
       //  READ   --  Lesen nächsten Eintrag                 *
       //----------------------------------------------------*
       //  Erforderliche Änderungen für anderes List API     *
       //    - *NONE                                         *
       //====================================================*
       begsr READ;

          o_count = -1;
          o_module  = '';

          if (numRecords > 0);

             pPgml0100 = pLstHdr + lstHdr.ofsLstSct +
               ((lstHdr.numE - numRecords) *
               lstHdr.sizeE);
             numRecords = numRecords - 1;

             o_count = numRecords;
             o_module = pgml0100;

          endif;

       endsr;

      /end-free
     P                 E

       //====================================================*
       //  Check user space existance                        *
       //====================================================*
     P existUserSpace...
     P                 B
     D                 PI              n
     D  i_qUsrSpc                          const likeds(qObj_t)
      /free

       clCmd = 'CHKOBJ OBJ(' + %trim(qUsrSpc.lib) + '/'
                             + %trim(qUsrSpc.name) + ') OBJTYPE(*USRSPC)';

       monitor;
          QCMDEXC(clCmd: %len(clCmd));
       on-error;
          return *off;
       endmon;

       return *on;

      /end-free
     P                 E

       //=====================================================================*
       //                                                                     *
       //  Kurzdokumentation :                                                *
       //                                                                     *
       //  Bereich . . . : DSPSRC                                             *
       //  Objekt  . . . : DSPSRCR2                                           *
       //  Beschreibung  : Tool: DSPSRC     (Display Source Code)             *
       //  Author  . . . : Thomas Raddatz   <thomas.raddatz@tools400.de>      *
       //  Datum . . . . : 25.07.2001                                         *
       //                                                                     *
       //=====================================================================*
       //                                                                     *
       //  This software is free software, you can redistribute it and/or     *
       //  modify it under the terms of the GNU General Public License (GPL)  *
       //  as published by the Free Software Foundation.                      *
       //                                                                     *
       //  See GNU General Public License for details.                        *
       //          http://www.opensource.org                                  *
       //          http://www.opensource.org/licenses/gpl-license.html        *
       //                                                                     *
       //=====================================================================*
       //  History:                                                           *
       //                                                                     *
       //  Datum       Name          Änderung                                 *
       //  ----------  ------------  ---------------------------------------  *
       //  10.01.2003  Th.Raddatz    Removed special character § from source. *
       //  01.03.2007  Th.Raddatz    Wrong option in module selection subfile *
       //                            was not correctly processed. Added       *
       //                            'DSPATR(PC)' to SFPAU.                   *
       //  08.02.2019  Th.Raddatz    Converted to /free.                      *
       //                                                                     *
       //=====================================================================*
       // >>PRE-COMPILER<<                                                    *
       //   >>CRTCMD<< CRTRPGMOD    MODULE(&LI/&OB) +                         *
       //                           SRCFILE(&SL/&SF) +                        *
       //                           SRCMBR(&SM);                              *
       //   >>IMPORTANT<<                                                     *
       //     >>PARM<< TRUNCNBR(*NO);                                         *
       //     >>PARM<< DBGVIEW(*LIST);                                        *
       //     >>PARM<< OPTION(*EVENTF);                                       *
       //   >>END-IMPORTANT<<                                                 *
       //   >>EXECUTE<<                                                       *
       // >>END-PRE-COMPILER<<                                                *
       //=====================================================================*
     H NOMAIN
      /COPY QDSPSRC,H_SPEC
      /COPY QDSPSRC,COPYRIGHT

     FDSPSRCD   CF   E             WORKSTN USROPN
     F                                     INFDS(WORKSTN)
     F                                     SFILE(PBSFL:RECNO)
     F                                     indds(wrkstn_flags)

      /copy qdspsrc,types_h
      /copy qdspsrc,workstn
      /copy qdspsrc,qbnlspgm
      /copy qdspsrc,qbnlpgmi

     D wrkstn_flags    DS                  qualified
     D sflDsp                 80     80n
     D sflEnd                         1n
     D sflDspCtl                      1n
     D sflNxtChg                      1n
     D sfpau_pc                       1n


     D RECNO           S             10I 0

     D WORKSTN         DS                  likeds(workstn_infds_t)

     D spgl0100        DS                  likeds(spgl0100_t)
     D pgml0100        DS                  likeds(pgml0100_t)

     D module          DS                  qualified
     D pgm                           10
     D pgmLib                        10
     D mod                           10
     D modLib                        10
     D srcFile                       10
     D srcLib                        10
     D srcMbr                        10

     D isFound         S               n

     D cTRUE           C                   CONST('1')
     D cFALSE          C                   CONST('0')

     D yCount          S             10p 0
     D yModule         DS           512

       //*******************************************************************
       //  Program entry point                                             *
       //*******************************************************************
     P DSPSRCR2...
     P                 B                   export
     D                 PI
     D  i_qObj                       20A   const
     D  i_objType                    10A   const
     D  i_autoSelect                   N   const
     D  o_qSrcFile                               likeds(qObj_t)
     D  o_srcMbr                     10A
     D  o_rc                         10A
       //---------------------------------------------------*
      /free

       //  Subfile record number
       RECNO = 0;

       //  "Not found"  flag
       isFound = cFALSE;

       o_rc = '';
       o_qSrcFile = '';
       o_srcMbr = '';

       exsr CRTLST;

       select;
       //  No more entries available
       when (yCount <= 0);
          return;

       //  Only one module found, select it automatically
       when (yCount = 1 AND i_autoSelect);
          exsr REDLST;
          exsr FILLSF;
          exsr FILLEL;
          return;

       //  More than one module available, let the user select
       other;
          OPEN DSPSRCD;
          exsr VREFR;
       endsl;

       dow '1';

          write PBBOT;

          //  If there are no module ...
          if (not wrkstn_flags.sflDsp);
             //  ... display 'not found' message
             write PBLEER;
          endif;

          EXFMT PBCTL;

          select;
          when (workstn.aid = cKeyF3);
             o_rc = '*CANCEL';
             LEAVE;
          when (workstn.aid = cKeyF5);
             exsr VREFR;
             iter;
          when (workstn.aid = cKeyF12);
             o_rc = '*CANCEL';
             LEAVE;
          when (workstn.aid = cKeyEnter);
             exsr VSFL;
             if (isFound = cTRUE);
                LEAVE;
             else;
                iter;
             endif;
          other;
             iter;
          endsl;

       enddo;

       //---------------------------------------------------*
       //  Close program
       close DSPSRCD;

       exsr DELLST;

       return;

       //====================================================*
       //  Refresh screen                                    *
       //====================================================*

       begsr VREFR;

          exsr CRTLST;

          exsr PBCLR;
          exsr PBFL;

       endsr;

       //====================================================*
       //  Read changed subfile records                      *
       //====================================================*

       begsr VSFL;

          //  "Not found"
          isFound = cFALSE;

          if (not wrkstn_flags.sflDsp);
             //  Keine Einträge vorhanden ...
          else;

             dou %eof(DSPSRCD);
                READC PBSFL;
                //  "Is found"
                if (not %eof(DSPSRCD));
                   select;
                   when (SFPAU = '');
                      wrkstn_flags.sflNxtChg = *off;
                      wrkstn_flags.sfpau_pc = *off;
                      UPDATE PBSFL;
                   when (SFPAU = '1');
                      SFPAU = '';
                      wrkstn_flags.sflNxtChg = *off;
                      wrkstn_flags.sfpau_pc = *off;
                      UPDATE PBSFL;
                      exsr FILLEL;
                      isFound = cTRUE;
                   other;
                      wrkstn_flags.sflNxtChg = *on;
                      wrkstn_flags.sfpau_pc = *on;
                      UPDATE PBSFL;
                      LEAVE;
                   endsl;
                endif;

             enddo;

          endif;

       endsr;

       //====================================================*
       //  Set return values from selected module            *
       //====================================================*

       begsr FILLEL;

          o_qSrcFile = $$SRCF + $$SRCL;
          o_srcMbr = $$SRCM;

       endsr;

       //====================================================*
       //  Create module list                                *
       //====================================================*

       begsr CRTLST;

          yModule = '';

          if (i_objType = '*PGM');
             DSPSRCR1(i_qObj: '1': yCount: yModule);
          else;
             DSPSRCR3(i_qObj: '1': yCount: yModule);
          endif;

       endsr;

       //====================================================*
       //  Delete module list                                *
       //====================================================*

       begsr DELLST;

          if (i_objType = '*PGM');
             DSPSRCR1(i_qObj: '4': yCount: yModule);
          else;
             DSPSRCR3(i_qObj: '4': yCount: yModule);
          endif;

       endsr;

       //====================================================*
       //  Read next module entry from list                  *
       //====================================================*

       begsr REDLST;

          if (i_objType = '*PGM');
             DSPSRCR1(i_qObj: '5': yCount: yModule);
             pgml0100 = yModule;
             module.pgm = pgml0100.pgm;
             module.pgmLib = pgml0100.pgmLib;
             module.mod = pgml0100.mod;
             module.modLib = pgml0100.modLib;
             module.srcFile = pgml0100.srcFile;
             module.srcLib = pgml0100.srcLib;
             module.srcMbr = pgml0100.srcMbr;
          else;
             DSPSRCR3(i_qObj: '5': yCount: yModule);
             spgl0100 = yModule;
             module.pgm = spgl0100.srvPgm;
             module.pgmLib = spgl0100.srvPgmLib;
             module.mod = spgl0100.mod;
             module.modLib = spgl0100.modLib;
             module.srcFile = spgl0100.srcFile;
             module.srcLib = spgl0100.srcLib;
             module.srcMbr = spgl0100.srcMbr;
          endif;

       endsr;

       //====================================================*
       //  Clear subfile                                     *
       //====================================================*

       begsr PBCLR;

          wrkstn_flags.sflDsp = *off;
          wrkstn_flags.sflDspCtl = *off;
          WRITE PBCTL;
          wrkstn_flags.sflDspCtl = *on;

          wrkstn_flags.sflEnd = *on;

          RECNO = 0;
          SFSANR = 1;

       endsr;

       //====================================================*
       //  Fill subfile ith module list                      *
       //====================================================*

       begsr PBFL;

          dow (yCount > 0);

             RECNO = RECNO + 1;
             exsr REDLST;
             exsr FILLSF;

             //  If there is only one module in the list, ...
             if (yCount = 1 and RECNO = 1);
                //  ... then select it automatically
                wrkstn_flags.sflNxtChg = *on;
                SFPAU = '1';
             else;
                //  ... else let the user select the module
                wrkstn_flags.sflNxtChg = *off;
                SFPAU = '';
             endif;

             wrkstn_flags.sfpau_pc = *off;

             WRITE PBSFL;
             wrkstn_flags.sflDsp = *on;
          enddo;

       endsr;

       //====================================================*
       //  Populate subfile fields                           *
       //====================================================*

       begsr FILLSF;

          SFPAU = '';
          $$MDNM = module.mod;
          $$MDLB = module.modLib;
          $$SRCF = module.srcFile;
          $$SRCL = module.srcLib;
          $$SRCM = module.srcMbr;

       endsr;

      /end-free
     P                 E

